private void ExportToHTML()
{
    if (dtbData == null || dtbData.Rows.Count == 0)
    {
        MessageManager.Warning("Không có dữ liệu để xuất!");
        return;
    }

    DataView dvData = dtbData.DefaultView;
    string strOldFilter = dvData.RowFilter;
    dvData.RowFilter = gvData.RowFilter;

    try
    {
        DataTable dtbExport = dvData.ToTable();
        if (dtbExport.Rows.Count == 0)
        {
            MessageManager.Warning("Không có dữ liệu để xuất!");
            return;
        }

        List<string> lstTeacherID = GetDistinctTeacherIDs(dtbExport);
        if (lstTeacherID.Count == 0)
        {
            MessageManager.Warning("Không có dữ liệu giảng viên để xuất!");
            return;
        }

        string strLastFile = "";
        foreach (string strTeacherID in lstTeacherID)
        {
            strLastFile = ExportTeacherHTML(dtbExport, strTeacherID);
        }

        if (strLastFile != "")
            System.Diagnostics.Process.Start(strLastFile);
    }
    finally
    {
        dvData.RowFilter = strOldFilter;
    }
}

private static List<string> GetDistinctTeacherIDs(DataTable dtbExport)
{
    List<string> lstTeacherID = new List<string>();

    foreach (DataRow row in dtbExport.Rows)
    {
        string strTeacherID = row["TeacherID"] == DBNull.Value
            ? ""
            : row["TeacherID"].ToString().Trim();

        if (strTeacherID == "")
            continue;

        if (!lstTeacherID.Contains(strTeacherID))
            lstTeacherID.Add(strTeacherID);
    }

    lstTeacherID.Sort(StringComparer.CurrentCulture);
    return lstTeacherID;
}

private string ExportTeacherHTML(DataTable dtbExport, string strTeacherID)
{
    DataRow[] arrRows = dtbExport.Select(
        String.Format("TeacherID = '{0}'", strTeacherID.Replace("'", "''")));

    if (arrRows == null || arrRows.Length == 0)
        return "";

    DataRow drwFirst = arrRows[0];
    StringBuilder sbDetail = new StringBuilder();
    decimal decTongSoTiet = 0;
    decimal decTongQuyDoi = 0;
    int intStt = 1;

    foreach (DataRow row in arrRows)
    {
        decimal decLT = ToDecimal(row["TotalQuantity_Theory"]);
        decimal decTH = ToDecimal(row["TotalQuantity_Practice"]);
        decimal decTongLTTH = ToDecimal(row["TongLTTH"]);
        decimal decClassSize = ToDecimal(row["ClassSize"]);
        decimal decHeSo = ToDecimal(row["HeSo"]);
        decimal decQuyDoiGio = ToDecimal(row["QuyDoiGio"]);
        decimal decHeSoHienThi = decHeSo * GetHeSoSiSo(decClassSize);

        if (decHeSo == 0)
            decHeSoHienThi = GetHeSoSiSo(decClassSize);

        decTongSoTiet += decTongLTTH;
        decTongQuyDoi += decQuyDoiGio;

        sbDetail.Append("<tr>");
        sbDetail.AppendFormat("<td>{0}</td>", intStt);
        sbDetail.AppendFormat("<td>{0}</td>", GetLoaiHienThi(decLT, decTH));
        sbDetail.AppendFormat("<td>{0}</td>", HtmlEncode(GetColumnText(row, "SubjectID")));
        sbDetail.AppendFormat(
            "<td class=\"text-left\">{0}</td>",
            HtmlEncode(GetColumnText(row, "SubjectName")));
        sbDetail.AppendFormat("<td>{0}</td>", HtmlEncode(GetColumnText(row, "ClassID")));
        sbDetail.AppendFormat("<td>{0}</td>", HtmlEncode(GetColumnText(row, "Semester")));
        sbDetail.AppendFormat("<td>{0}</td>", FormatNumber(decClassSize, 0));
        sbDetail.AppendFormat("<td>{0}</td>", FormatNumber(decTongLTTH, 3));
        sbDetail.AppendFormat("<td>{0}</td>", GetDayNightMark(row));
        sbDetail.AppendFormat("<td>{0}</td>", FormatNumber(decHeSoHienThi, 3));
        sbDetail.AppendFormat("<td>{0}</td>", FormatNumber(decQuyDoiGio, 3));
        sbDetail.Append("<td>&nbsp;</td>");
        sbDetail.Append("</tr>");

        intStt++;
    }

    string strFileName = "BangTinhGioDayGiangVien.htm";
    string strFileContent = Libs.Files.ReadFile(strFileName);

    strFileContent = strFileContent.Replace("{HEADER_LEFT}", BuildHeaderLeft());
    strFileContent = strFileContent.Replace("{HEADER_RIGHT}", BuildHeaderRight());
    strFileContent = strFileContent.Replace("{YEAR}", GetYearText());
    strFileContent = strFileContent.Replace("{DOT}", GetDotText());
    strFileContent = strFileContent.Replace("{TEACHER_INFO}", BuildTeacherInfo(drwFirst));
    strFileContent = strFileContent.Replace("{DONVI}", HtmlEncode(GetTeacherDonVi(drwFirst)));
    strFileContent = strFileContent.Replace("{DETAIL}", sbDetail.ToString());
    strFileContent = strFileContent.Replace("{TONG_GIO_QUY_DOI}", FormatNumber(decTongQuyDoi, 2));
    strFileContent = strFileContent.Replace("{TONG_SO_TIET}", FormatNumber(decTongSoTiet, 3));
    strFileContent = strFileContent.Replace("{SO_MON_LOP}", arrRows.Length.ToString());
    strFileContent = strFileContent.Replace("{PLACE_DATE}", BuildPlaceDate());
    strFileContent = strFileContent.Replace("{TEACHER_NAME_SIGN}", HtmlEncode(GetTeacherFullName(drwFirst)));

    string strFileNameAs = String.Format(
        "{0}_{1}_{2}",
        strTeacherID,
        DateTime.Now.ToString("yyyyMMdd_HHmmss"),
        strFileName);

    Libs.Files.WriteFile(strFileNameAs, strFileContent);
    return strFileNameAs;
}

private string BuildHeaderLeft()
{
    string strHeader = SYS_SettingService.GetStringValue("Report_Header_Text");
    if (string.IsNullOrEmpty(strHeader))
        strHeader = "TRƯỜNG CAO ĐẲNG HUẾ";

    return FormatHeaderBlock(strHeader);
}

private string BuildHeaderRight()
{
    string strHeader = SYS_SettingService.GetStringValue("Report_Header2_Text");
    if (string.IsNullOrEmpty(strHeader))
    {
        strHeader =
            "CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM" + Environment.NewLine +
            "Độc lập - Tự do - Hạnh phúc";
    }

    return FormatHeaderBlock(strHeader);
}

private static string FormatHeaderBlock(string strHeader)
{
    if (string.IsNullOrEmpty(strHeader))
        return "&nbsp;";

    string[] arrLines = strHeader.Split(
        new string[] { "\r\n", "\n" },
        StringSplitOptions.None);

    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < arrLines.Length; i++)
    {
        string strLine = arrLines[i].Trim();
        if (strLine == "")
            continue;

        if (i == 0)
            sb.AppendFormat("<div class=\"line1\">{0}</div>", HtmlEncode(strLine));
        else if (i == 1)
            sb.AppendFormat("<div class=\"line2\">{0}</div>", HtmlEncode(strLine));
        else
            sb.AppendFormat("<div>{0}</div>", HtmlEncode(strLine));
    }

    return sb.ToString();
}

private string GetYearText()
{
    if (uYearSemester.YearEditValueText != null
        && uYearSemester.YearEditValueText.Trim() != "")
    {
        return uYearSemester.YearEditValueText;
    }

    return "";
}

private string GetDotText()
{
    if (uYearSemester.SemesterEditValue != null
        && uYearSemester.SemesterEditValue.ToString().Trim() != "")
    {
        return String.Format(
            "Học kỳ: {0}",
