}

private string BuildTeacherInfo(DataRow row)
{
    string strDegree = GetColumnText(row, "TeacherDegree");
    string strFullName = GetTeacherFullName(row);
    string strTeacherID = GetColumnText(row, "TeacherID");

    if (strDegree != "")
        return String.Format("GV-{0}: {1} ({2})", strDegree, strFullName, strTeacherID);

    return String.Format("GV: {0} ({1})", strFullName, strTeacherID);
}

private static string GetTeacherFullName(DataRow row)
{
    string strFirstName = GetColumnText(row, "TeacherFirstName");
    string strLastName = GetColumnText(row, "TeacherLastName");
    string strFullName = (strFirstName + " " + strLastName).Trim();

    if (strFullName != "")
        return strFullName;

    if (row.Table.Columns.Contains("TeacherName"))
        return GetColumnText(row, "TeacherName");

    return "";
}

private string GetTeacherDonVi(DataRow row)
{
    if (row.Table.Columns.Contains("ScienceName"))
    {
        string strScienceName = GetColumnText(row, "ScienceName");
        if (strScienceName != "")
            return strScienceName;
    }

    if (uSubjectGroup.ScienceEditValue != null)
        return uSubjectGroup.ScienceEditValue.ToString();

    return "";
}

private string BuildPlaceDate()
{
    string strPlace = SYS_SettingService.GetStringValue("Report_Place");
    if (string.IsNullOrEmpty(strPlace))
        strPlace = "Huế";

    DateTime dtmNow = SYS_SettingService.CurrentDateTime;
    return String.Format(
        "{0}, ngày {1} tháng {2} năm {3}",
        strPlace,
        dtmNow.Day,
        dtmNow.Month,
        dtmNow.Year);
}

private static string GetLoaiHienThi(decimal decLT, decimal decTH)
{
    if (decLT > 0 && decTH > 0)
        return "LT+TH";

    if (decTH > 0)
        return "TH";

    return "LT";
}

private static string GetDayNightMark(DataRow row)
{
    if (row.Table.Columns.Contains("IsNightTeaching"))
    {
        object objValue = row["IsNightTeaching"];
        if (objValue != null && objValue != DBNull.Value)
        {
            if (Convert.ToBoolean(objValue))
                return "X";
        }
    }

    if (row.Table.Columns.Contains("IsSundayTeaching"))
    {
        object objValue = row["IsSundayTeaching"];
        if (objValue != null && objValue != DBNull.Value)
        {
            if (Convert.ToBoolean(objValue))
                return "X";
        }
    }

    return "&nbsp;";
}

private static string GetColumnText(DataRow row, string strColumnName)
{
    if (!row.Table.Columns.Contains(strColumnName))
        return "";

    if (row[strColumnName] == null || row[strColumnName] == DBNull.Value)
        return "";

    return row[strColumnName].ToString().Trim();
}

private static string FormatNumber(decimal decValue, int intDecimalDigits)
{
    string strFormat = "#,##0";
    if (intDecimalDigits > 0)
        strFormat = String.Format("#,##0.{0}", new string('0', intDecimalDigits));

    return decValue.ToString(strFormat);
}

private static string HtmlEncode(string strValue)
{
    if (string.IsNullOrEmpty(strValue))
        return "";

    return strValue
        .Replace("&", "&amp;")
        .Replace("<", "&lt;")
        .Replace(">", "&gt;")
        .Replace("\"", "&quot;");
}

