private static string ReadHtmlTemplate(string strFileName)
{
    string strContent = "";

    try
    {
        strContent = Libs.Files.ReadFile(strFileName);
    }
    catch
    {
        strContent = "";
    }

    if (!string.IsNullOrEmpty(strContent))
        return strContent;

    string strTemplatePath = Path.Combine(
        Application.StartupPath,
        "MauHTML",
        strFileName);

    if (File.Exists(strTemplatePath))
    {
        try
        {
            return File.ReadAllText(strTemplatePath, Encoding.UTF8);
        }
        catch
        {
            return "";
        }
    }

    MessageManager.Warning(
        String.Format(
            "Không tìm thấy file mẫu HTML:{0}{1}{0}Hãy copy file mẫu vào thư mục MauHTML của chương trình.",
            Environment.NewLine,
            strTemplatePath));

    return "";
}

private static string WriteHtmlFile(string strFileNameAs, string strFileContent)
{
    if (string.IsNullOrEmpty(strFileContent))
        return "";

    string strExportFolder = Path.Combine(Application.StartupPath, "Export");
    if (!Directory.Exists(strExportFolder))
        Directory.CreateDirectory(strExportFolder);

    string strFullPath = Path.Combine(strExportFolder, strFileNameAs);

    try
    {
        File.WriteAllText(strFullPath, strFileContent, new UTF8Encoding(true));
        return strFullPath;
    }
    catch (Exception ex)
    {
        MessageManager.Warning("Không ghi được file HTML: " + ex.Message);
        return "";
    }
}

