    List<string> lstTeacherID = GetDistinctTeacherIDs(dtbExport);
    if (lstTeacherID.Count == 0)
    {
        MessageManager.Warning("Không có dữ liệu giảng viên để xuất!");
        return;
    }

    string strLastFile = "";
    foreach (string strTeacherID in lstTeacherID)
    {
        string strFilePath = ExportTeacherHTML(dtbExport, strTeacherID);
        if (strFilePath != "")
            strLastFile = strFilePath;
    }

    if (strLastFile == "")
    {
        MessageManager.Warning("Xuất HTML không thành công!");
        return;
    }

    System.Diagnostics.Process.Start(strLastFile);
}

private static List<string> GetDistinctTeacherIDs(DataTable dtbExport)
{
    List<string> lstTeacherID = new List<string>();

    foreach (DataRow row in dtbExport.Rows)
    {
        string strTeacherID = row["TeacherID"] == DBNull.Value
            ? ""
            : row["TeacherID"].ToString().Trim();

        if (strTeacherID == "")
            continue;

        if (!lstTeacherID.Contains(strTeacherID))
            lstTeacherID.Add(strTeacherID);
    }

    lstTeacherID.Sort(StringComparer.CurrentCulture);
    return lstTeacherID;
}

