}

private string BuildHeaderRight()
{
    string strHeader = SYS_SettingService.GetStringValue("Report_Header2_Text");
    if (string.IsNullOrEmpty(strHeader))
    {
        strHeader =
            "CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM" + Environment.NewLine +
            "Độc lập - Tự do - Hạnh phúc";
    }

    return FormatHeaderBlock(strHeader, false);
}

private static string FormatHeaderBlock(string strHeader, bool isLeft)
{
    if (string.IsNullOrEmpty(strHeader))
        return "&nbsp;";

    string[] arrLines = strHeader.Split(
        new string[] { "\r\n", "\n" },
        StringSplitOptions.None);

    List<string> lstLines = new List<string>();
    for (int i = 0; i < arrLines.Length; i++)
    {
        string strLine = arrLines[i].Trim();
        if (strLine != "")
            lstLines.Add(strLine);
    }

    if (lstLines.Count == 0)
        return "&nbsp;";

    StringBuilder sb = new StringBuilder();

    if (isLeft)
    {
        if (lstLines.Count >= 2)
        {
            sb.AppendFormat("<div class=\"line1-normal\">{0}</div>", HtmlEncode(lstLines[0]));
            sb.AppendFormat("<div class=\"line2-bold\">{0}</div>", HtmlEncode(lstLines[1]));
        }
        else
        {
            sb.AppendFormat("<div class=\"line2-bold\">{0}</div>", HtmlEncode(lstLines[0]));
        }
    }
    else
    {
        sb.AppendFormat("<div class=\"line1-bold\">{0}</div>", HtmlEncode(lstLines[0]));
        if (lstLines.Count >= 2)
            sb.AppendFormat("<div class=\"line2-underline\">{0}</div>", HtmlEncode(lstLines[1]));
    }

    sb.Append("<div class=\"header-underline\"></div>");
    return sb.ToString();
}

