private string ApplySummaryPlaceholders(
    string strFileContent,
    DataRow drwTeaching,
    decimal decTongQuyDoiGiangDay,
    string strTeacherID)
{
    DataRow drwSummary = LoadTeacherSummaryRow(strTeacherID);
    DataRow drwSource = drwSummary != null ? drwSummary : drwTeaching;

    string strKy1Label;
    string strKy2Label;
    BuildPeriodLabels(out strKy1Label, out strKy2Label);

    decimal decTongGioQuyDoi = decTongQuyDoiGiangDay;
    if (decTongGioQuyDoi == 0)
        decTongGioQuyDoi = GetDecimalFromRow(drwSource, "TongSoGioGiangDayHoatDong");

    decimal decDinhMucGdKy1 = GetDecimalFromRow(drwSource, "StandardQuantity_DinhMucGiangDay");
    decimal decDinhMucGdKy2 = GetDecimalFromRow(
        drwSource,
        "StandardQuantity_DinhMucGiangDay2",
        "StandardQuantity_DinhMucGiangDay_HK2");
    decimal decTongDinhMucGdNam = GetDecimalFromRow(
        drwSource,
        "RealStandardQuantity_DinhMucGiangDayNamHoc");

    if (decTongDinhMucGdNam == 0 && decDinhMucGdKy1 + decDinhMucGdKy2 > 0)
        decTongDinhMucGdNam = decDinhMucGdKy1 + decDinhMucGdKy2;

    decimal decDinhMucHDCD = GetDecimalFromRow(
        drwSource,
        "DinhMucHoatDongCongDong",
        "StandardQuantity_HoatDongCongDong");
    if (decDinhMucHDCD == 0)
        decDinhMucHDCD = 0;

    decimal decTongGioHDCD = GetDecimalFromRow(
        drwSource,
        "TotalFinal_W35_HoatDongKhac",
        "TongGioHoatDongCongDong");
    decimal decGioThuaThieuHDCD = decTongGioHDCD - decDinhMucHDCD;

    decimal decDinhMucNVCM = GetDecimalFromRow(
        drwSource,
        "RatioPositionValue_DinhMucGiamKiemNhiem",
        "StandardQuantity_NhiemVuChuyenMon",
        "DinhMucNVCM");

    decimal decTongGioNCKH = GetDecimalFromRow(drwSource, "ResearchNow_NCKH");
    decimal decGioBaoLuuNCKHTruoc = GetDecimalFromRow(
        drwSource,
        "ResearchReserve_PreviousYear",
        "SoGioBaoLuuNCKHNamTruoc");
    decimal decDinhMucNCKH = GetDecimalFromRow(
        drwSource,
        "StandardQuantity_NCKH",
        "DinhMucNCKH");
    if (decDinhMucNCKH == 0)
        decDinhMucNCKH = 0;

    decimal decGioThieuNCKH = GetDecimalFromRow(drwSource, "SoGioThieuNCKH");
    if (decGioThieuNCKH == 0 && decDinhMucNCKH > 0)
    {
        decimal decChenhNCKH = decDinhMucNCKH - decTongGioNCKH - decGioBaoLuuNCKHTruoc;
        if (decChenhNCKH > 0)
            decGioThieuNCKH = decChenhNCKH;
    }

    decimal decGioBaoLuuNCKHSau = GetDecimalFromRow(
        drwSource,
        "ResearchReserve_NextYear",
        "SoGioBaoLuuNCKHNamSau");

    decimal decGioThieuHDCD = 0;
    if (decGioThuaThieuHDCD < 0)
        decGioThieuHDCD = Math.Abs(decGioThuaThieuHDCD);

    decimal decSoGioVuotDinhMuc = decTongGioQuyDoi
        - decTongDinhMucGdNam
        - decGioThieuNCKH
        - decGioThieuHDCD
        - decDinhMucNVCM;

    if (decSoGioVuotDinhMuc < 0)
        decSoGioVuotDinhMuc = 0;

    strFileContent = strFileContent.Replace("{KY1_LABEL}", strKy1Label);
    strFileContent = strFileContent.Replace("{KY2_LABEL}", strKy2Label);
    strFileContent = strFileContent.Replace("{TONG_GIO_QUY_DOI}", FormatSummaryNumber(decTongGioQuyDoi, 2));
    strFileContent = strFileContent.Replace("{DINH_MUC_GD_KY1}", FormatSummaryNumber(decDinhMucGdKy1, 2));
    strFileContent = strFileContent.Replace("{DINH_MUC_GD_KY2}", FormatSummaryNumber(decDinhMucGdKy2, 2));
    strFileContent = strFileContent.Replace("{TONG_DINH_MUC_GD_NAM}", FormatSummaryNumber(decTongDinhMucGdNam, 2));
    strFileContent = strFileContent.Replace("{DINH_MUC_HDCD}", FormatSummaryNumber(decDinhMucHDCD, 1));
    strFileContent = strFileContent.Replace("{TONG_GIO_HDCD}", FormatSummaryNumber(decTongGioHDCD, 1));
    strFileContent = strFileContent.Replace("{GIO_THUA_THIEU_HDCD}", FormatSummarySignedNumber(decGioThuaThieuHDCD, 1));
    strFileContent = strFileContent.Replace("{DINH_MUC_NVCM}", FormatSummaryNumber(decDinhMucNVCM, 2));
    strFileContent = strFileContent.Replace("{TONG_GIO_NCKH}", FormatSummaryNumber(decTongGioNCKH, 0));
    strFileContent = strFileContent.Replace("{GIO_BAO_LUU_NCKH_TRUOC}", FormatSummaryNumber(decGioBaoLuuNCKHTruoc, 0));
    strFileContent = strFileContent.Replace("{DINH_MUC_NCKH}", FormatSummaryNumber(decDinhMucNCKH, 0));
    strFileContent = strFileContent.Replace("{GIO_THIEU_NCKH}", FormatSummaryNumber(decGioThieuNCKH, 0));
    strFileContent = strFileContent.Replace("{GIO_BAO_LUU_NCKH_SAU}", FormatSummaryNumber(decGioBaoLuuNCKHSau, 0));
    strFileContent = strFileContent.Replace("{SO_GIO_VUOT_DINH_MUC}", FormatSummaryNumber(decSoGioVuotDinhMuc, 2));

    return strFileContent;
}

private DataRow LoadTeacherSummaryRow(string strTeacherID)
{
    try
    {
        SIM_Branch obj = new SIM_Branch();
        string strSemester = "1";

        if (uYearSemester.SemesterEditValue != null
            && uYearSemester.SemesterEditValue.ToString().Trim() != "")
        {
            strSemester = uYearSemester.SemesterEditValue.ToString().Trim();
        }

        DataTable dtbSummary = obj.GetDataTable(
            "SIM_Schedule_TK_KetQuaThucHienNhaGiao",
            "@ScienceIDOfTeacher", uSubjectGroup.ScienceEditValue,
            "@SubjectGroupIDOfTeacher", uSubjectGroup.SubjectGroupEditValue,
            "@TeacherID", strTeacherID,
            "@YearID", uYearSemester.YearIDEditValue,
            "@TeacherTypeID", null,
            "@chkNOTlaiXe", false,
            "@Semester", strSemester);

        if (dtbSummary != null && dtbSummary.Rows.Count > 0)
            return dtbSummary.Rows[0];
    }
    catch
    {
    }

    return null;
}

private void BuildPeriodLabels(out string strKy1Label, out string strKy2Label)
{
    int intStartYear = 0;
    int intEndYear = 0;
    string strYearText = GetYearText();

    if (!string.IsNullOrEmpty(strYearText))
    {
        string[] arrParts = strYearText.Split('-');
        if (arrParts.Length >= 2)
        {
            int.TryParse(arrParts[0].Trim(), out intStartYear);
            int.TryParse(arrParts[1].Trim(), out intEndYear);
        }
    }

    if (intStartYear > 0 && intEndYear > 0)
    {
        strKy1Label = String.Format(
            "từ tháng 09/{0}-tháng 03/{1}",
