private static decimal GetDecimalFromRow(DataRow row, params string[] arrColumnNames)
{
    if (row == null || arrColumnNames == null)
        return 0;

    foreach (string strColumnName in arrColumnNames)
    {
        DataColumn col = FindColumn(row.Table, strColumnName);
        if (col == null)
            continue;

        if (row[col] == null || row[col] == DBNull.Value)
            continue;

        return ToDecimal(row[col]);
    }

    return 0;
}

private static string FormatSummaryNumber(decimal decValue, int intDecimalDigits)
{
    return FormatNumber(decValue, intDecimalDigits);
}

private static string FormatSummarySignedNumber(decimal decValue, int intDecimalDigits)
{
    if (decValue == 0)
        return FormatNumber(0, intDecimalDigits);

    string strValue = FormatNumber(Math.Abs(decValue), intDecimalDigits);
    if (decValue > 0)
        return "+" + strValue;

    return "-" + strValue;
}

